    export const getRejectDeploymentUrl = (id: string,) => {




  return `/api/v1/deployments/${id}/reject`
}

/**
 * Ends the deployment as `failed` with a detail naming the rejecter and their reason. No container is ever touched, because the deploy never started. The reason is required.
 * @summary Reject a parked deploy (approver rank, session only)
 */
export const rejectDeployment = async (id: string,
    rejectDeploymentRequest: RejectDeploymentRequest, options?: RequestInit): Promise<Deployment> => {

  return apiFetch<Deployment>(getRejectDeploymentUrl(id),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(rejectDeploymentRequest)
  }
);}





